        : _Del_base(std::move(__d)), _Alloc_base(__a), _M_ptr(__p)
        { }

        _Deleter& _M_del() noexcept { return _Del_base::_S_get(*this); }
        _Alloc& _M_alloc() noexcept { return _Alloc_base::_S_get(*this); }

